/* Relative specifiers are required, not cosmetic. A bare "tokens/x.css" is a
   valid relative URL to a browser, so the CDN path never noticed, but css-loader
   and other bundler CSS pipelines read a non-relative specifier as a module
   request into node_modules and fail to resolve it. "./" works everywhere. */
@import "./tokens/layers.css";
@import "./tokens/fonts.css";
@import "./tokens/colors.css";
@import "./tokens/typography.css";
@import "./tokens/spacing.css";
@import "./tokens/effects.css";
@import "./tokens/base.css";

/* Element defaults live in @layer meridian with the components. Unlayered, they
   beat every layered rule, so Tailwind utilities (mt-*, leading-*, font-*,
   tracking-*) on h1-h4 and p silently lost. Inside the layer they sit below
   `components` and `utilities` in the order tokens/layers.css registers, and
   unlayered product CSS still wins by CSS definition. Element selectors carry
   less specificity than any .ef-* class, so components in the same layer keep
   their own margins, fonts and colours. */
@layer meridian{
/* The gap between a label and its icon. Meridian-level aliases of the space scale: spacing.css is
   vendored from design-tokens, so these live here until design-tokens carries them.
   --gap-label-icon is an inline text and icon pair; --gap-label-icon-sm is the small controls (Badge, Button xs, Link). */
:root{--gap-label-icon:var(--space-2);--gap-label-icon-sm:var(--space-1)}
/* The accent coloured word of a heading or a script title (MD109). One alias of --accent-edge, so the dark and both
   increased-contrast tables follow it. It sits on :root and on every [data-theme] element: a themed subtree
   resolves its own --accent-edge, not the root's. A product deletes its own --accent-word remap. */
:root,[data-theme]{--accent-word:var(--accent-edge)}
/* The dimmest opacity of a loading pulse (Loader pulse, GeneratedImage status, Task, Reasoning, ToolCall). A pulse keeps
   running under reduce (MD122), so axe or a reader can land on its dimmest frame: the text must pass there too.
   Measured from the tokens in light and dark, on every surface (page, card, subtle, sunken, elevated): the lowest opacity
   at which --text-muted still has 4.5:1 is .91 in light and .87 in dark (the Loader on --surface-sunken is the
   strictest); --text-secondary .82, --text-primary .61, the GeneratedImage status on its media backdrop .62, and the
   Reasoning glyph (a mark, 3:1) .71. One value for all, above the strictest. */
:root{--ef-pulse-floor:.92}
/* One turn of every rotating spinner (Spinner, the Button spinner, the glyph spinners of AgentRun, Sandbox, Todo and
   ToolCall), always with linear (MD129; owner decision 2026-11-28: 1.4 s was too slow for a loading indicator). It waits
   for a design-tokens row DT --dur-spin and then moves there: effects.css is vendored, so it is defined here until then. */
:root{--dur-spin:800ms}
/* Icons: the box and the scale sizes here, so the markup carries no style attribute (strict CSP).
   A size off the scale is set through the CSSOM by Icon. */
[data-slot="icon"]{display:inline-flex;flex:none;color:inherit}
[data-slot="icon"][data-size="8"]{width:var(--icon-xs);height:var(--icon-xs)}
[data-slot="icon"][data-size="12"]{width:var(--icon-sm);height:var(--icon-sm)}
[data-slot="icon"][data-size="16"]{width:var(--icon-md);height:var(--icon-md)}
[data-slot="icon"][data-size="20"]{width:var(--icon-lg);height:var(--icon-lg)}
[data-slot="icon"][data-size="24"]{width:var(--icon-xl);height:var(--icon-xl)}
[data-slot="icon"][data-size="32"]{width:var(--icon-2xl);height:var(--icon-2xl)}
body{margin:0;font-family:var(--font-sans);font-size:var(--text-md);line-height:var(--leading-normal);color:var(--text-primary);background:var(--surface-page);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,h4{font-family:var(--font-display);letter-spacing:var(--tracking-display);line-height:var(--leading-snug);margin:0}
p{margin:0}
/* Link defaults must not outrank layered component variants, including hover.
   Zero specificity also lets .ef-btn keep its foreground within this layer. */
:where(a){color:var(--text-link);text-decoration:none;transition:color var(--dur-fast) var(--ease-enter)}
:where(a:hover){color:var(--text-link-hover);text-decoration:none}
/* A link in running text is underlined: the link colour is 2.43:1 against the body ink in light and 1.88:1 in dark
   (WCAG 1.4.1). Classless anchors inside text blocks only; a component anchor has its own class and its own rule.
   Text blocks (MD92): p, dd, blockquote, figcaption, li, td, caption, label (a consent line with a link in it) and the
   Alert description. Not covered, on purpose: th (a header is a label, its link is a sort or a navigation control),
   summary (the disclosure control), dt (a term) and the list or nav containers themselves. Navigation is not covered
   either (MD97): a classless link inside nav, [role=navigation], [role=menu], [role=menubar], [role=tablist] or
   [role=toolbar] stays plain, however deep, because its cue is its place, not the underline. The exclusion is
   :not(:is(...) *) inside the same :where(), so the specificity stays 0,0,1 and a layered component rule still wins
   (supported: Chrome 88, Firefox 84, Safari 9). A link with a class keeps the :not([class]) opt-out. This rule is
   unlayered on purpose: the :where(a) default above is unlayered too and would beat a layered component rule. */
:where(p, dd, blockquote, figcaption, li, td, caption, label, .ef-alert__description) a:where(:not([class]):not(:is(nav, [role=navigation], [role=menu], [role=menubar], [role=tablist], [role=toolbar]) *)){text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:.2em}
:where(p, dd, blockquote, figcaption, li, td, caption, label, .ef-alert__description) a:where(:not([class]):not(:is(nav, [role=navigation], [role=menu], [role=menubar], [role=tablist], [role=toolbar]) *)):hover{text-decoration-thickness:2px}
:where(a:focus-visible){outline:none;box-shadow:var(--focus-ring);border-radius:var(--radius-sm)}
code,pre,kbd{font-family:var(--font-mono)}
::selection{background:var(--brand-100);color:var(--cocoa-900)}
*,*::before,*::after{box-sizing:border-box}
/* Layered !important outranks unlayered !important, so this holds against product
   CSS too. Delays are zeroed as well: a delayed reveal must not keep content
   hidden, or keep it waiting, under reduce. Transition durations are left to the
   tokens: under reduce they swap to the 120 ms fade (design-tokens docs/motion.md).
   --ef-motion-guard is the animation duration: 0.01 ms for every element, so loops stop. Only an overlay
   entrance or exit sets it, to --dur-fast, together with animation-name:ef-reduce-fade (opacity only), inside its
   own reduce media query; a consumer must not set it on a loop.
   Loops that signal LOADING are the exception (MD122): a spinner, a skeleton, a shimmer, an indeterminate bar and a
   stream pulse keep running at their own duration and curve, because a frozen spinner reads as a hung page. They are
   left out of the rule by name, and tests/md122-reduced-motion-guard.test.mjs fails an infinite animation that is
   neither listed there nor named as not loading (a caret, a marquee, a growing ring, a scaling bar: those stop).
   The exclusion is `:where()`, not `:is()`: `:is()` takes the specificity of its most specific argument (0,3,0 for the
   indeterminate progress bar), which would outrank an overlay's own `--ef-motion-guard:var(--dur-fast)` in the same
   layer and collapse its fade to .01 ms. With `:where()` the rule has no specificity and the overlay's value wins.
   A View Transition (document.startViewTransition) does not match `*`: its groups stop moving and its
   old and new snapshots cross-fade over --dur-fast. */
@keyframes ef-reduce-fade{from{opacity:0}}
/* The exit of an overlay (MD121) is the same fade backwards: the closed state of every overlay runs ef-reduce-fade-out
   over --dur-fast. Under reduce a closed element takes --dur-fast for the guard, so the guard below does not
   shorten it to .01 ms; its movement exit is written by the component inside no-preference. */
@keyframes ef-reduce-fade-out{to{opacity:0}}
@media (prefers-reduced-motion:reduce){[data-state="closed"]{--ef-motion-guard:var(--dur-fast)}}
@media (prefers-reduced-motion:reduce){*:not(:where(.ef-spinner,.ef-btn__spin,.ef-agentrun__spin,.ef-sandbox__spin,.ef-todo__spin,.ef-toolcall__spin,.ef-skel,.ef-table__skel,.ef-progress[data-state="indeterminate"] .ef-progress__indicator,.ef-loader--pulse,.ef-loader--shimmer,.ef-loader__dots span,.ef-attachment[data-state="uploading"] .ef-attachment__title,.ef-attachment[data-state="processing"] .ef-attachment__title,.ef-genimg__backdrop,.ef-genimg__status,.ef-reasoning--streaming .ef-reasoning__glyph,.ef-toolcall--pending .ef-toolcall__head,.ef-toolcall--streaming .ef-toolcall__row:last-child .ef-toolcall__val,.ef-task--streaming .ef-task__row:last-of-type)),*::before,*::after{--ef-motion-guard:.01ms;animation-duration:var(--ef-motion-guard)!important;animation-delay:0s!important;animation-iteration-count:1!important;transition-delay:0s!important;scroll-behavior:auto!important}}
@media (prefers-reduced-motion:reduce){::view-transition-group(*),::view-transition-image-pair(*){animation-duration:var(--ef-motion-guard)!important;animation-iteration-count:1!important}::view-transition-old(*),::view-transition-new(*){animation-duration:var(--dur-fast)!important;animation-iteration-count:1!important}}
/* Movement is off and opacity stays (MD127). A transition that turns or scales something does not run under reduce:
   a chevron turns at once, a tick and a dot appear at full size while their opacity fades over --dur-fast. Layered
   !important so a component rule written after it, and a product rule, do not bring the movement back. The press
   scale stays (Button, IconButton, Checkbox, Radio, the composer send, the slider thumb): it is brief feedback, not
   travel. tests/md122-reduced-motion-guard.test.mjs fails a transform transition that is neither here, nor a press,
   nor given its own reduce rule by its component. */
@media (prefers-reduced-motion:reduce){.ef-agentrun__toggle .ef-agentrun__tchev,.ef-reasoning__chev,.ef-sandbox__chev,.ef-todo__chev,.ef-toolcall__chev,.ef-console__stackchev,.ef-diff__filechev,.ef-exception__chev,.ef-acc__chev,.ef-tree__chev,.ef-navigation-menu__chevron,.ef-pagination__previous svg,.ef-pagination__next svg{transition:none!important}.ef-check__box svg,.ef-radio__dot::after,.ef-tile__check{transition-property:opacity!important}}
/* Theme switch (MD118). A swap changes every colour at once, and each element with a colour transition starts one,
   so the page smears (46 transitionrun events on the docs Components page, 22 on sso web). While <html> carries
   data-theme-switching every transition is off. ThemeToggle (and browser/marketing.js) sets the attribute, swaps the
   theme, and removes the attribute after two animation frames. Inside the layer on purpose: a layered !important
   outranks an unlayered one, so a product's own !important transition does not survive the swap. A product that
   switches the theme itself calls swapTheme(), or sets the attribute for the same two frames. Delete any local copy. */
[data-theme-switching] *,[data-theme-switching] *::before,[data-theme-switching] *::after{transition:none!important}
/* Warm glass (design-tokens docs/glass.md). One material, four thicknesses, all from material.* tokens.
   .ef-glass--blur only where content scrolls under it (bars, sheets, popovers); at most four on screen,
   never one inside another. The tokens turn every thickness solid under reduced transparency, more
   contrast and without backdrop-filter. .ef-glass-field is the quiet field behind the page that glass blurs. */
.ef-glass{background-color:color-mix(in srgb,var(--material-tint) calc(var(--ef-glass-alpha,var(--material-regular)) * 100%),transparent);background-image:linear-gradient(135deg,color-mix(in srgb,var(--text-on-media) calc(var(--material-sheen) * 100%),transparent),transparent 42%);border:1px solid color-mix(in srgb,var(--text-on-media) calc(var(--material-edge) * 100%),transparent);box-shadow:inset 0 1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec) * 100%),transparent),inset 0 -1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec-low) * 100%),transparent)}
.ef-glass--clear{--ef-glass-alpha:var(--material-clear)}
.ef-glass--regular{--ef-glass-alpha:var(--material-regular)}
.ef-glass--chrome{--ef-glass-alpha:var(--material-chrome);box-shadow:inset 0 1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec) * 100%),transparent),inset 0 -1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec-low) * 100%),transparent),var(--shadow-md)}
.ef-glass--thick{--ef-glass-alpha:var(--material-thick);box-shadow:inset 0 1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec) * 100%),transparent),inset 0 -1px 0 color-mix(in srgb,var(--text-on-media) calc(var(--material-spec-low) * 100%),transparent),var(--shadow-lg)}
.ef-glass--blur{-webkit-backdrop-filter:blur(var(--material-blur)) saturate(var(--material-saturate));backdrop-filter:blur(var(--material-blur)) saturate(var(--material-saturate))}
.ef-glass--thick.ef-glass--blur{-webkit-backdrop-filter:blur(var(--material-blur-thick)) saturate(var(--material-saturate));backdrop-filter:blur(var(--material-blur-thick)) saturate(var(--material-saturate))}
.ef-glass-field{position:relative;isolation:isolate;background-color:var(--field-0)}
.ef-glass-field::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:var(--field-strength);background:radial-gradient(60% 55% at 10% 6%,var(--field-1),transparent 70%),radial-gradient(55% 60% at 94% 16%,var(--field-3),transparent 72%),radial-gradient(70% 60% at 70% 96%,var(--field-2),transparent 70%)}
/* Shape (MD81): one root setting for the corners of everything you press and everything you type into.
   data-shape="pill" on <html> or <body> sets two properties: --press-radius (Button, IconButton, Tag, Badge,
   ButtonGroup text) to a full pill and --field-radius (Input, Textarea, NumberInput, Select, InputGroup and the other
   text fields) to --radius-md (16px). A subtree does not reach the portalled overlays (Dialog, Popover, Toast and the rest
   mount in document.body): pass `container` or set it on <html> or <body>. The components read the properties with
   today's radius as the fallback, so an absent attribute changes nothing. Fields are not full pills: a multi-line field
   with a full radius reads as a mistake. --radius-md is 16px here (what efolusi.com and sso web draw): Input sm (28px)
   is a stadium (radius over half the height), Input md and NativeSelect (36px) are near-stadiums, Input lg (44px),
   Input xl (52px) and Textarea are rounded rectangles. Toggle, ButtonTile, InputOTP slots and the Sidebar search input follow
   neither property. */
[data-shape="pill"]{--press-radius:var(--radius-full);--field-radius:var(--radius-md)}
/* Page title (MD83): the one title of a signed-in page or a plain page, written by sso, pay and efolusi.com each on
   its own. Display face at --text-3xl to --text-4xl, balanced, and a long word breaks instead of overflowing. Put it
   on the h1; marketing pages use Hero and sections use SectionHead. */
.ef-page-title{margin:0;font-family:var(--font-display);font-size:clamp(var(--text-3xl),4vw,var(--text-4xl));font-weight:var(--weight-bold);line-height:var(--leading-tight);letter-spacing:var(--tracking-display);text-wrap:balance;overflow-wrap:break-word}
/* Not-found page (MD110): the markup of the root 404.html, which products copy. Plain HTML, no script and no style
   attribute, so a strict CSP lets it render. It needs only this stylesheet. One mark, the status code, then the same
   message in English and Indonesian side by side, stacked on a phone. The link is drawn like a primary Button because
   the static stylesheet does not carry the component CSS. */
.ef-notfound{box-sizing:border-box;min-height:100vh;min-height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--space-4);padding:var(--space-16) var(--space-6);text-align:center}
.ef-notfound__mark{display:block;width:40px;height:40px}
.ef-notfound__code{margin:0;font-family:var(--font-mono);font-size:var(--text-sm);color:var(--text-muted)}
.ef-notfound__langs{display:grid;gap:var(--space-8);width:100%;max-width:56rem;margin-block-start:var(--space-4)}
.ef-notfound__lang{display:flex;flex-direction:column;align-items:center;gap:var(--space-4)}
.ef-notfound .ef-page-title{font-size:var(--text-3xl)}
.ef-notfound__lang p{margin:0;max-width:34ch;font-size:var(--text-lg);line-height:var(--leading-relaxed);color:var(--text-secondary)}
.ef-notfound__lang+.ef-notfound__lang{padding-block-start:var(--space-8);border-block-start:1px solid var(--border-default)}
.ef-notfound__home{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;min-height:var(--tap-min);margin-block-start:var(--space-2);padding:0 var(--space-5);border:1px solid var(--accent-edge);border-radius:var(--press-radius,var(--radius-sm));background:var(--accent);color:var(--accent-contrast);font-family:var(--font-sans);font-size:var(--text-md);font-weight:var(--weight-semibold);line-height:var(--leading-normal);text-decoration:none;white-space:nowrap;transition:background var(--dur-fast) var(--ease-enter)}
@media (prefers-reduced-motion:no-preference){.ef-notfound__home{transition:background var(--dur-fast) var(--ease-enter),transform var(--dur-fast) var(--ease-enter)}}
@media (hover:hover){.ef-notfound__home:hover{background:var(--accent-hover);text-decoration:none}}
.ef-notfound__home:active{background:var(--accent-active);transform:scale(var(--motion-press))}
.ef-notfound__home:focus-visible{outline:none;box-shadow:var(--focus-ring)}
@media (min-width:880px){.ef-notfound__langs{grid-auto-flow:column;grid-auto-columns:1fr;gap:var(--space-8)}.ef-notfound__lang+.ef-notfound__lang{padding-block-start:0;padding-inline-start:var(--space-8);border-block-start:0;border-inline-start:1px solid var(--border-default)}}
}
/* Phone control text (MD86): iOS Safari zooms the page when a text control takes focus while its text is under 16px,
   and Input md (14px), Input sm, Textarea, NumberInput, NativeSelect and the InputGroup control under Combobox are
   13 or 14px, as are the TimePicker, Command, Sidebar search, composer (PromptComposer, RichComposer), PromptSteps,
   WebPreview address, Questionnaire and InputOTP inputs. At phone widths every one of them is 16px, whatever its
   size prop. Unlayered on purpose, like the
   forced-colors rule below: it outranks the sized rules in @layer meridian whatever the source order, and a product's
   own unlayered rule that comes later can still choose a larger size. Sizes lg and xl are 16px already. */
@media (max-width:767px){.ef-input__el,.ef-input__el--sm,.ef-textarea,.ef-number__el,.ef-native-select select,.ef-input-group__control,.ef-combobox__chips-input,.ef-timepicker__input,.ef-command__input,.ef-sidebar-input,.ef-composer__input,.ef-richcomposer__input,.ef-promptsteps__other,.ef-webprev__addr,.ef-questionnaire__input,.ef-otp__input{font-size:16px}}
/* Forced colours (Windows High Contrast) remove box-shadow, and box-shadow is how
   every component draws --focus-ring after outline:none, so focus would vanish.
   Deliberately outside the layer: unlayered, it outranks the @layer meridian
   component rules, and !important makes it outrank a product's own `outline:none`
   too (MD78). An important declaration in a layer beats an unlayered one, so no
   component may carry an !important outline: tests/md78-forced-colors-focus.test.mjs
   scans them. Highlight is a system colour, so it survives the forced palette. */
@media (forced-colors:active){:focus-visible{outline:2px solid Highlight!important;outline-offset:2px}.ef-glass{background:Canvas;border-color:CanvasText;-webkit-backdrop-filter:none;backdrop-filter:none;box-shadow:none}.ef-glass-field::before{display:none}}

