  --surface-elevated: var(--surface-card);
  --surface-panel: var(--surface-card);
  --surface-card-hover: var(--surface-sunken);
  --surface-sunken: var(--sand-75);
  --surface-subtle: var(--sand-50);
  --surface-inverse: var(--sand-950);
  --surface-inverse-hover: var(--sand-900);
  --surface-inverse-active: var(--sand-800);
  --surface-brand: var(--brand-100);
  --surface-code: #14110B;
  --surface-track: var(--sand-200);
  --surface-brand-hover: var(--brand-200);
  --field-0: var(--sand-25);
  --field-1: var(--brand-100);
  --field-2: var(--brand-200);
  --field-3: var(--sand-150);
  --field-strength: var(--glass-strength);
  --text-code: #E8E3D9;
  --text-on-brand-muted: rgba(30,26,20,.75);
  --text-on-brand: var(--sand-950);
  --text-on-media: var(--sand-50);
  --text-on-media-muted: rgba(250,249,246,.75);
