@font-face{font-family:'Bricolage Grotesque';src:url('https://cdn.jsdelivr.net/npm/@efolusi/meridian-tokens@2.6.0/assets/fonts/BricolageGrotesque-Variable.woff2') format('woff2-variations');font-weight:200 800;font-style:normal;font-display:swap}
@font-face{font-family:'Figtree';src:url('https://cdn.jsdelivr.net/npm/@efolusi/meridian-tokens@2.6.0/assets/fonts/Figtree-Variable.woff2') format('woff2-variations');font-weight:300 900;font-style:normal;font-display:swap}
@font-face{font-family:'Figtree';src:url('https://cdn.jsdelivr.net/npm/@efolusi/meridian-tokens@2.6.0/assets/fonts/Figtree-Italic-Variable.woff2') format('woff2-variations');font-weight:300 900;font-style:italic;font-display:swap}
